import React from "react";
import SinglePost from "./singelPostComponent";

class Home extends React.Component {

    constructor(props){
        super(props);

        this.state = {
            data: [],
            loading: 'a'
        };
    }

    componentDidMount() {
        console.log('Home Mounted');

        fetch("http://localhost:8000/test")  // ← این را با URL واقعی API جایگزین کن
            .then(res => {
                this.setState({
                    loading: 'b'
                });
            })
            .then(data => {
                this.setState({
                    loading: 'c'
                });
                
            })
            .catch(err => {
                this.setState({
                    loading: 'sn'
                });
                console.log();
                
            });
    }

    render() {
        return (
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">

                    {this.state.loading}

                </div>
            </main>
        );
    }
}

export default Home;
